download::DownloadItemImpl* CreateActiveDownloadItem(uint32_t id, const download::DownloadCreateInfo& info) {
    // Check if a download with the given id already exists
    if (downloads.find(id) != downloads.end()) {
        return nullptr;
    }

    // Create a new download item using the provided information
    download::DownloadItemImpl* item = new download::DownloadItemImpl(info);

    // Store it in the downloads map
    downloads[id] = item;

    // Attach additional information to the download item
    item->AttachInfo(info);

    return item;
}

download::DownloadItemImpl* CreateActiveDownloadItem(uint32_t id, const download::DownloadCreateInfo& info) {
    // Check if a download with the given id already exists
    if (download_manager.DoesDownloadExist(id)) {
        return nullptr;
    }

    // Create a new download item using the provided information
    download::DownloadItemImpl* new_download = new download::DownloadItemImpl(id, info);

    // Store it in the downloads map
    download_manager.AddDownload(id, new_download);

    // Attach additional information to the download item
    new_download->AttachAdditionalInfo();

    return new_download;
}

download::DownloadItemImpl* CreateDownloadItem(uint32_t id, const download::DownloadCreateInfo& info) {
    // Check if a download with the given id already exists
    if (download::DownloadManager::Contains(id)) {
        return nullptr;
    }

    // Create a new download item using the provided information
    download::DownloadItemImpl* item = new download::DownloadItemImpl(info);

    // Store it in the downloads map
    download::DownloadManager::Add(id, item);

    // Attach additional information to the download item
    item->AttachInfo(info);

    return item;
}
